using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns JsonTypeInfo<T> directly (no cast needed).
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → {personInfo.Type.Name}  (instance: {personInfo.GetType().Name})");

// 2. TryGetTypeInfo — probe without throwing.
//    Returns true + the metadata when the resolver knows about the type;
//    returns false + null when it doesn't.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"TryGetTypeInfo(Person)  → found: {found!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo(Person)  → not found");

// Try a type that a source-gen-only resolver wouldn't know about
// (with the default reflection resolver it *will* resolve, so we
//  demonstrate with an empty TypeInfoResolver to show the "not found" path).
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // resolves nothing
};

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? missing))
    Console.WriteLine($"TryGetTypeInfo(Person, limited) → found: {missing!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo(Person, limited) → not found (no throw!)");

record Person(string Name, int Age);

